package com.hssa.auth.service; import com.hssa.auth.dto.request.*; import com.hssa.auth.dto.response.AuthenticationResponse; import com.hssa.auth.dto.response.TokenResponse; import jakarta.servlet.http.HttpServletRequest; public interface AuthService { void register(RegisterRequest request); AuthenticationResponse login(LoginRequest request, HttpServletRequest httpRequest); TokenResponse refreshToken(RefreshTokenRequest request); void logout(String sessionToken); void forgotPassword(ForgotPasswordRequest request); void resetPassword(ResetPasswordRequest request); void changePassword(ChangePasswordRequest request, String email); void verifyEmail(VerifyEmailRequest request); }
